//! Generates the typed catalog key constants from `locales/en.toml`.
//!
//! The ids are frozen and never edited by hand: the build turns every message
//! id into a `Key` constant, so a call site cannot pass an arbitrary string.
//! A malformed catalog, a duplicate id or two ids that map to the same Rust
//! constant produce a `compile_error!` in the generated file instead of a
//! failing build script.

use std::collections::{BTreeMap, BTreeSet};
use std::env;
use std::fmt::Write as _;
use std::fs;
use std::path::PathBuf;

fn main() {
    println!("cargo:rerun-if-changed=locales/en.toml");
    let generated = fs::read_to_string("locales/en.toml").map_or_else(
        |error| compile_error(&format!("cannot read locales/en.toml: {error}")),
        |source| generate(&source),
    );
    let Some(out_dir) = env::var_os("OUT_DIR") else {
        println!("cargo:warning=OUT_DIR is unset; cannot generate keys.rs");
        return;
    };
    let path = PathBuf::from(out_dir).join("keys.rs");
    if let Err(error) = fs::write(&path, generated) {
        println!("cargo:warning=cannot write {}: {error}", path.display());
    }
}

fn generate(source: &str) -> String {
    match parse(source) {
        Ok(entries) => render(&entries),
        Err(message) => compile_error(&message),
    }
}

fn parse(source: &str) -> Result<Vec<Entry>, String> {
    let value = toml::from_str::<toml::Value>(source)
        .map_err(|error| format!("locales/en.toml is not valid TOML: {error}"))?;
    let messages = value
        .get("messages")
        .and_then(toml::Value::as_table)
        .ok_or_else(|| "locales/en.toml has no [messages] table".to_owned())?;
    let mut entries = Vec::with_capacity(messages.len());
    let mut ids = BTreeSet::new();
    let mut names: BTreeMap<String, String> = BTreeMap::new();
    for (id, value) in messages {
        if value.as_str().is_none() {
            return Err(format!("locales/en.toml id {id:?} is not a string"));
        }
        if !ids.insert(id.clone()) {
            return Err(format!("locales/en.toml repeats the id {id:?}"));
        }
        let name = constant_name(id)
            .ok_or_else(|| format!("locales/en.toml id {id:?} has no usable constant name"))?;
        if name == "ALL" {
            return Err(format!(
                "locales/en.toml id {id:?} maps to the reserved constant ALL"
            ));
        }
        if let Some(previous) = names.insert(name.clone(), id.clone()) {
            return Err(format!(
                "locales/en.toml ids {previous:?} and {id:?} both map to the constant {name}"
            ));
        }
        entries.push(Entry {
            id: id.clone(),
            name,
        });
    }
    entries.sort_by(|left, right| left.id.cmp(&right.id));
    Ok(entries)
}

/// Uppercases an id and replaces every non-alphanumeric character with `_`.
fn constant_name(id: &str) -> Option<String> {
    let mut name = String::with_capacity(id.len() + 1);
    for character in id.chars() {
        if character.is_ascii_alphanumeric() {
            name.push(character.to_ascii_uppercase());
        } else {
            name.push('_');
        }
    }
    if name.is_empty() || name == "_" {
        return None;
    }
    if name.as_bytes().first().is_some_and(u8::is_ascii_digit) {
        name.insert(0, '_');
    }
    Some(name)
}

fn render(entries: &[Entry]) -> String {
    let mut out = String::from(
        "// @generated by build.rs from locales/en.toml. Do not edit.\n\nuse super::Key;\n\n",
    );
    if write_keys(&mut out, entries).is_err() {
        return compile_error("cannot render keys.rs");
    }
    out
}

fn write_keys(out: &mut String, entries: &[Entry]) -> std::fmt::Result {
    for entry in entries {
        let id = entry.id.escape_default();
        writeln!(out, "/// Catalog id `{id}`.")?;
        writeln!(out, "pub const {}: Key = Key::new(\"{id}\");\n", entry.name)?;
    }
    writeln!(out, "/// Every catalogued key, in stable id order.")?;
    writeln!(out, "pub const ALL: &[Key] = &[")?;
    for entry in entries {
        writeln!(out, "    {},", entry.name)?;
    }
    writeln!(out, "];")
}

fn compile_error(message: &str) -> String {
    format!("compile_error!(\"{}\");\n", message.escape_default())
}

struct Entry {
    id: String,
    name: String,
}
